```python
def infix_to_prefix(self, infix: str) -> str:
    def priority(element):
        if element=="^":
            return 3
        elif element=="*" or element=="/":
            return 2
        elif element=="+" or element=="-":
            return 1
        else:
            return 0
    def infix2postfix(infix):
        stack=[]
        ans=""
        for c in infix:
            if c.isalnum():
                ans+=c
            elif c=="(":
                stack.append(c)
            elif c==")":
                while stack and stack[-1]!="(":
                    ans+=stack.pop()
                stack.pop()
            else:
                if c=="^":
                    while stack and priority(c)<=priority(stack[-1]):
                        ans+=stack.pop()
                    stack.append(c)
                else:
                    while stack and priority(c)<priority(stack[-1]):
                        ans+=stack.pop()
                    stack.append(c)
        while stack:
            ans+=stack.pop()
        return ans
    def infix2prefix(infix):
        infix=infix[::-1]
        infix=infix.replace("(","temp").replace(")","(").replace("temp",")")
        prefix=infix2postfix(infix)
        return prefix[::-1]
    return infix2prefix(infix)
